function GridMinTwoClass(k, beta, N):
    best <- +infinity
    for a in {1/N, ..., (N-1)/N}:
        denom <- 2*a*(1-a)
        for p in {0, 1/N, ..., 1}:
            for r in {0, 1/N, ..., 1}:
                q <- (beta - a^2*p - (1-a)^2*r) / denom
                if q not in [0,1]: continue
                d1 <- a*p + (1-a)*q;  d2 <- a*q + (1-a)*r
                val <- a*d1^k*(1-d1) + (1-a)*d2^k*(1-d2)
                best <- min(best, val)
    return best
